Protects a worksheet, hides its gridlines, sets a row height and column width, and merges a cell range with Cells.Merge; round-trips the workbook through an in-memory XLSX stream and reads the protection state, gridline visibility and merged-region count back from the reloaded sheet.

Example:
// Authored example: configure worksheet protection, layout, and merged cells
using Aspose.Cells_FOSS;

var workbook = new Workbook();
var sheet = workbook.Worksheets[0];
sheet.Name = "Layout";
sheet.TabColor = Color.FromArgb(255, 34, 68, 102);
sheet.ShowGridlines = false;
sheet.Zoom = 85;
sheet.Protect();
sheet.Protection.InsertRows = true;
sheet.Protection.SelectLockedCells = true;

sheet.Cells["A1"].PutValue("Merged Header");
sheet.Cells.Rows[0].Height = 24.0;
sheet.Cells.Columns[0].Width = 20.0;
sheet.Cells.Merge(0, 0, 1, 3);

using var stream = new MemoryStream();
workbook.Save(stream, SaveFormat.Xlsx);
stream.Position = 0;
var loaded = new Workbook(stream);
var loadedSheet = loaded.Worksheets["Layout"];

Console.WriteLine("gridlines: " + loadedSheet.ShowGridlines);
Console.WriteLine("protected: " + loadedSheet.Protection.IsProtected);
Console.WriteLine("insert rows blocked: " + loadedSheet.Protection.InsertRows);
Console.WriteLine("merged regions: " + loadedSheet.Cells.MergedCells.Count);

if (loadedSheet.ShowGridlines)
{
    throw new Exception("gridlines should be hidden");
}
if (!loadedSheet.Protection.IsProtected)
{
    throw new Exception("worksheet should be protected");
}
if (loadedSheet.Cells.MergedCells.Count != 1)
{
    throw new Exception("expected exactly one merged region");
}
