Builds a minimal PNG byte array in memory, anchors it to a worksheet with Worksheet.Pictures.Add, names the picture, round-trips the workbook through an in-memory XLSX stream and reads the picture count, name, image type and anchor back from the reloaded sheet.

Example:
// Authored example: embed pictures anchored to worksheet cells
using Aspose.Cells_FOSS;

var workbook = new Workbook();
var sheet = workbook.Worksheets[0];
sheet.Cells["A1"].PutValue("Logo");

byte[] pngBytes = CreateTinyPng();

var pictureIndex = sheet.Pictures.Add(1, 1, 4, 4, pngBytes);
var picture = sheet.Pictures[pictureIndex];
picture.Name = "Logo Image";

using var stream = new MemoryStream();
workbook.Save(stream, SaveFormat.Xlsx);
stream.Position = 0;
var loaded = new Workbook(stream);
var loadedSheet = loaded.Worksheets[0];

Console.WriteLine("picture count: " + loadedSheet.Pictures.Count);
Console.WriteLine(loadedSheet.Pictures[0].Name + " (" + loadedSheet.Pictures[0].ImageType + ")");
Console.WriteLine("anchor: R" + loadedSheet.Pictures[0].UpperLeftRow + "C" + loadedSheet.Pictures[0].UpperLeftColumn);

if (loadedSheet.Pictures.Count != 1)
{
    throw new Exception("expected exactly one picture");
}
if (loadedSheet.Pictures[0].Name != "Logo Image")
{
    throw new Exception("name mismatch");
}
if (loadedSheet.Pictures[0].ImageType != ImageType.Png)
{
    throw new Exception("image type mismatch");
}

static byte[] CreateTinyPng()
{
    using var ms = new MemoryStream();
    byte[] header = { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A };
    ms.Write(header, 0, header.Length);
    WriteChunk(ms, "IHDR", new byte[] { 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x02, 0x00, 0x00, 0x00 });
    WriteChunk(ms, "IDAT", new byte[] { 0x78, 0x9C, 0x62, 0x00, 0x02, 0x00, 0x00, 0x05, 0x00, 0x01, 0x0D });
    WriteChunk(ms, "IEND", Array.Empty<byte>());
    return ms.ToArray();
}

static void WriteChunk(MemoryStream ms, string type, byte[] data)
{
    byte[] lengthBytes = BitConverter.GetBytes(data.Length);
    if (BitConverter.IsLittleEndian)
    {
        Array.Reverse(lengthBytes);
    }
    ms.Write(lengthBytes, 0, 4);
    byte[] typeBytes = System.Text.Encoding.ASCII.GetBytes(type);
    ms.Write(typeBytes, 0, 4);
    if (data.Length > 0)
    {
        ms.Write(data, 0, data.Length);
    }
    uint crc = Crc32(typeBytes, data);
    byte[] crcBytes = BitConverter.GetBytes(crc);
    if (BitConverter.IsLittleEndian)
    {
        Array.Reverse(crcBytes);
    }
    ms.Write(crcBytes, 0, 4);
}

static uint Crc32(byte[] typeBytes, byte[] data)
{
    uint crc = 0xFFFFFFFF;
    byte[] buffer = new byte[typeBytes.Length + data.Length];
    Buffer.BlockCopy(typeBytes, 0, buffer, 0, typeBytes.Length);
    Buffer.BlockCopy(data, 0, buffer, typeBytes.Length, data.Length);
    foreach (byte b in buffer)
    {
        crc ^= b;
        for (int i = 0; i < 8; i++)
        {
            crc = (crc & 1) != 0 ? (crc >> 1) ^ 0xEDB88320 : crc >> 1;
        }
    }
    return ~crc;
}
